import os
from lib.TokenizationCore import PianoArrangerTokenizer

TARGET_IN_DIR = "../04_augmented"
TARGET_OUT_DIR = "../40_phase2_tokens"

# We point directly to the config generated by Phase 1
CONFIG_PATH = "../30_phase1_tokens/tokenizer_config.json"


def run_phase2_tokenization():
    print("--- Starting Phase 2 Tokenization ---")

    if not os.path.exists(CONFIG_PATH):
        print(f"CRITICAL ERROR: Could not find {CONFIG_PATH}.")
        print(
            "Please run PHASE1_build_master_vocab.py first to establish the vocabulary."
        )
        return

    # 1. Initialize the Core object
    core = PianoArrangerTokenizer()

    # 2. Inherit the EXACT state from Phase 1
    core.load_existing(CONFIG_PATH)

    # 3. Process the Augmented target dataset
    print(f"\nProcessing Augmented Target Data from {TARGET_IN_DIR}...")
    core.process_directory(TARGET_IN_DIR, TARGET_OUT_DIR)

    # Note: We do NOT need to save the config again, as Phase 1 already acts as the source of truth.

    print("\n--- Phase 2 Tokenization Complete ---")


if __name__ == "__main__":
    run_phase2_tokenization()
